# ABILITY PLAN (fight micro, one change): cast order and cast targets in fights.
# 1. Stun-capable slot goes first (stun before burst), so the enemy is held before damage lands.
# 2. An AoE slot is cast at the target's tile (cast_at_tile), so it hits the group around it.
# 3. Shield and heal slots fire on self only when hurt (below 70% health), not on cooldown idle.
# 4. Attack resets are never cast at an enemy (they fail there); they stay self-cast after a basic attack.
# Everything else is v1 (monolith claim commit, vision wards, lock once, cast-ahead, tribute, camp farming).

def fight_cast(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot):
            if health() < 0.7 * max_health():
                cast_self(slot)
        elif slot_is_heal(slot):
            if health() < 0.7 * max_health():
                cast_self(slot)
        elif slot_is_aoe(slot):
            cast_at_tile(slot, unit_position(u))
        elif not slot_is_dash(slot) and not slot_is_reset(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

